const emails = $('EA Read').all();
const ctx    = $('Fetch Context').all();   // 1:1 with emails (one row per email)
const out = [];
for (let i = 0; i < emails.length; i++) {
  const it = emails[i].json;
  const c  = ctx[i] ? ctx[i].json : {};
  const rules    = c.rules    || '(none yet)';
  const examples = c.examples || '(none yet)';
  const routeSystem =
    "You are an Executive Assistant triaging and handling one email for your principal. " +
    "Decide ONE route, then act. Output STRICT JSON only - no prose, no fences:\n" +
    "{ \"route\": \"reply|review|task|fyi|ignore\", \"summary\": \"<=12 words\", " +
    "\"reply_subject\": \"\", \"reply_body\": \"\", \"task_title\": \"\", " +
    "\"due_date\": \"YYYY-MM-DD or empty\", \"why\": \"\", \"suggested_action\": \"<one concrete next step, or empty>\" }\n" +
    "Routes: reply = a straightforward response you can draft; review = needs a human " +
    "decision (proposal, contract, money, commitments); task = a to-do that is not an " +
    "email; fyi = no action; ignore = not actually actionable.\n" +
    "Drafting: match the sender register AND the EXAMPLES of how the principal writes; " +
    "be concise; use ONLY facts in the email - never invent commitments, dates, numbers, " +
    "or names. You DRAFT/PROPOSE only; a human sends.\n" +
    "Standing rules (obey these):\n" + rules;
  const routeUser =
    "From: " + (it.from_addr || '') + "\nSubject: " + (it.subject || '') + "\n\n" +
    (it.body || '') + "\n\n--- How the principal has replied to this sender before ---\n" + examples;
  out.push({ json: Object.assign({}, it, { routeSystem: routeSystem, routeUser: routeUser }) });
}
return out;

const src = $('Build Route Prompt').all();
const all = $input.all();
const out = [];

// Account map -- GiveSendGo is Outlook; Commissioned + personal are Gmail.
const MAILBOXES = {
  givesendgo:   { kind: 'outlook' },
  commissioned: { kind: 'gmail', email: 'nslafter@commissioned.io' },
  gmail:        { kind: 'gmail', email: 'nslafter@gmail.com' },
};

for (let i = 0; i < all.length; i++) {
  const o = src[i] ? src[i].json : {};
  const resp = all[i] ? all[i].json : {};
  let text = '';
  try { text = resp.content[0].text; } catch (e) {}
  let d = { route: 'fyi', summary: o.subject || '' };
  if (text) {
    const m = text.replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
    if (m) { try { d = JSON.parse(m[0]); } catch (e) {} }
  }
  let route = (d.route || 'fyi').toLowerCase();

  // Never file an unreadable email as a review item.
  if (route === 'review' && !String(o.body || '').trim()) route = 'fyi';

  // message_id + per-mailbox open link
  const mid  = o.message_id || o.internetMessageId || '';
  const acct = String(o.account || '').toLowerCase();
  const box  = MAILBOXES[acct] || {};
  const web_link =
    o.web_link || (box.kind === 'outlook' ? (o.webLink || null)
    : (box.kind === 'gmail' && mid)
      ? 'https://mail.google.com/mail/?authuser=' + encodeURIComponent(box.email)
        + '#search/rfc822msgid:' + encodeURIComponent(mid)
      : null);

  // priority int (1 = GiveSendGo) -> text for the attention table
  const priority_text = (d.priority && ['high','medium','low'].includes(String(d.priority).toLowerCase()))
    ? String(d.priority).toLowerCase()
    : (Number(o.priority) === 1 ? 'high' : 'medium');

  const base = { id: o.id, account: o.account, priority: o.priority,
                 route: route,
                 message_id: mid, web_link: web_link,
                 from_addr: o.from_addr || '', subject: o.subject || '',
                 summary: d.summary || '', source_message_id: mid };

  if (route === 'reply') {
    out.push({ json: Object.assign({}, base, {
      target: 'ea_actions', reply_body: d.reply_body || '',
      payload: { to: [o.from_addr], subject: d.reply_subject || ('Re: ' + (o.subject || '')),
                 body: d.reply_body || '', in_reply_to: mid || null, web_link: web_link },
      dedup_key: 'reply:' + (mid || o.id) }) });
  } else if (route === 'review') {
    out.push({ json: Object.assign({}, base, {
      target: 'attention', title: o.subject || 'Needs review',
      priority_text: priority_text,
      ask: d.why || d.suggested_action || '',
      why: d.why || '', suggested_action: d.suggested_action || '',
      source_body: o.body || '',
      dedup_key: 'review:' + (mid || o.id) }) });
  } else if (route === 'task') {
    out.push({ json: Object.assign({}, base, {
      target: 'tasks', task_title: d.task_title || (o.subject || 'Follow up'),
      due_date: d.due_date || null,
      dedup_key: 'task:' + (mid || o.id) }) });
  } else {
    out.push({ json: Object.assign({}, base, { target: 'none' }) });
  }
}
return out;
